<template>
  <view class="mpb-page" :style="miniProgramNavigationStyle"><view class="mpb-safe" /><view class="mpb-header"><button class="mpb-back" aria-label="返回" @click="backOrHome('/pages/agent/AgentCommissionPage')">‹</button><image class="mpb-logo" :src="loginLogo" mode="aspectFit" /><view class="mpb-header-copy"><text class="mpb-title">分润详情</text><text class="mpb-subtitle">订单归属与结算状态</text></view><text class="mpb-role agent">代理商</text></view><view class="mpb-stack"><view v-if="loading" class="mpb-card mpb-empty"><text class="mpb-empty-title">正在加载分润...</text></view><template v-else-if="item"><view class="mpb-hero"><view class="mpb-hero-top"><view><text class="mpb-hero-label">分润金额</text><text class="mpb-hero-value">{{ formatCurrency(rowNumber(item, 'amountCents', 'amount')) }}</text></view><text class="mpb-hero-badge success">{{ statusText(rowString(item, 'status', 'settleStatus')) }}</text></view><text class="mpb-hero-copy">该记录来自代理商分润接口，按订单和分润规则生成。</text></view><view class="mpb-card mpb-list"><view class="mpb-row"><text class="mpb-row-icon">单</text><view class="mpb-row-main"><text class="mpb-row-title">来源订单</text><text class="mpb-row-meta">{{ rowString(item, 'orderId') || '-' }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon green">规</text><view class="mpb-row-main"><text class="mpb-row-title">分润规则</text><text class="mpb-row-meta">{{ rowString(item, 'ruleId', 'commissionType', 'source') || '平台规则' }}</text></view></view><view class="mpb-row"><text class="mpb-row-icon orange">时</text><view class="mpb-row-main"><text class="mpb-row-title">创建时间</text><text class="mpb-row-meta">{{ formatDate(rowString(item, 'createdAt', 'settledAt')) }}</text></view></view></view></template><view v-else class="mpb-card mpb-empty"><text class="mpb-empty-title">未找到分润记录</text></view></view></view>
</template>
<script setup lang="ts">
import { ref } from "vue"; import { onLoad } from "@dcloudio/uni-app"; import { api } from "../../api/client"; import { asRecord, backOrHome, formatCurrency, formatDate, rowNumber, rowString, statusText, type AnyRecord } from "../../utils/miniProgramBusiness"; import loginLogo from "../../assets/zhiqiyun-logo-transparent.png";
const id=ref(""); const loading=ref(false); const item=ref<AnyRecord|null>(null); async function load(){loading.value=true;try{const payload=asRecord(await api(`/api/v1/channel/commissions/${encodeURIComponent(id.value)}`));const detail=asRecord(payload.item);item.value=rowString(detail,"id","commissionId")?detail:null;}catch(error){uni.showToast({title:error instanceof Error?error.message:"分润加载失败",icon:"none"});}finally{loading.value=false;}} onLoad(options=>{id.value=String(options?.id||"");void load();});
</script>
<style>@import "../../styles/mini-program-business.css";</style>
